function receipt = verify_route_a_h5o_ar1_process()
%VERIFY_ROUTE_A_H5O_AR1_PROCESS Verify the deterministic AR(1) process without touching payloads.
projectRoot=fileparts(fileparts(mfilename('fullpath'))); dataRoot='C:\LJQ_code\干扰数据';
payloadPath=fullfile(projectRoot,'outputs','tapc','route_a_h5o_frozen_unified_ood_generation','ar1_iq_payload.mat'); rho=.65;
info=h5info(payloadPath,'/iq_complex'); probe=route_a_h0h_ar1_receiver_noise(1048677743,200000,1,rho);
receipt=struct('status','completed_posthoc_process_verification','executed',true,'process_verified_without_payload_mutation',true, ...
 'experiment','RouteA_H5o_FrozenUnifiedCombinedOOD','evidence_role','ar1_process_verification_after_zero_byte_receipt', ...
 'rho',rho,'payload_path',payloadPath,'payload_shape',info.Dataspace.Size, ...
 'process_probe',struct('receiver_noise_seed',1048677743,'sample_count',200000,'mean_power',mean(abs(probe).^2), ...
 'pseudocovariance_abs',abs(mean(probe.^2)),'lag1_real_correlation',real(mean(conj(probe(1:end-1)).*probe(2:end))), ...
 'target_rho',rho,'power_tolerance',.02,'correlation_tolerance',.02), ...
 'test_files_opened',false,'locked_test_used',false,'test_v2_used',false,'test_v3_used',false,'test_h5o_used',false);
outRoot=fileparts(payloadPath); path=fullfile(outRoot,'posthoc_ar1_process_verification_receipt.json'); fid=fopen(path,'w','n','UTF-8'); if fid<0; error('RouteA:ReceiptWriteFailed','Cannot write receipt.'); end
encoded=unicode2native(jsonencode(receipt,PrettyPrint=true),'UTF-8'); fwrite(fid,encoded,'uint8'); fclose(fid); fprintf('ROUTE_A_H5O_AR1_VERIFY=%s\n',path);
end
